use super::*;
use semio_framework_test_fixtures::fixture_text;
struct OriginalSchemaWallet{grant:RetainedCloneGrant,progress:RetainedCloneProgress}
impl ReceivingWallet for OriginalSchemaWallet{

 fn admit_frontier(&self,demand:RetainedCloneGrant)->Result<()>{let remaining=RetainedCloneGrant{maximum_items:self.grant.maximum_items-self.progress.copied_items,maximum_copy_bytes:self.grant.maximum_copy_bytes-self.progress.copied_bytes,..self.grant};if demand.maximum_items>remaining.maximum_items{return Err(error(ValueRefusalKind::WorkLimit,"original schema work grant refused"))}if demand.maximum_copy_bytes>remaining.maximum_copy_bytes||demand.maximum_capacity_bytes>remaining.maximum_capacity_bytes||demand.maximum_release_bytes>remaining.maximum_release_bytes||demand.maximum_depth>remaining.maximum_depth{return Err(error(ValueRefusalKind::OwnershipLimit,"original schema physical grant refused"))}Ok(())}
 fn record_progress(&mut self,progress:RetainedCloneProgress)->Result<()>{self.progress=self.progress.checked_add(progress)?;Ok(())}
 fn allocate_vec_into<T>(&mut self,_:&mut NativeDecodeControl<'_>,_:usize,_:&mut Vec<T>,_:usize)->Result<()>{Err(error(ValueRefusalKind::UnsupportedOwner,"borrowed schema validator has no allocating operation"))}
 fn allocate_encode_vec_into<T>(&mut self,_:&mut NativeEncodeControl<'_>,_:usize,_:&mut Vec<T>,_:usize)->Result<()>{Err(error(ValueRefusalKind::UnsupportedOwner,"borrowed schema validator has no allocating operation"))}
 fn copy_text_into(&mut self,_:&mut NativeDecodeControl<'_>,_:&str,_:&mut String,_:usize)->Result<()>{Err(error(ValueRefusalKind::UnsupportedOwner,"borrowed schema validator has no text producer"))}
 fn copy_encode_text_into(&mut self,_:&mut NativeEncodeControl<'_>,_:&str,_:&mut String,_:usize)->Result<()>{Err(error(ValueRefusalKind::UnsupportedOwner,"borrowed schema validator has no text producer"))}
}
#[test]
fn sqlite_snapshot_receiving_borrowed_schema_uses_original_work_without_owned_tokens(){
 use std::{io::Write,process::{Command,Stdio}};
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🧩️artifact/🫴️receiving/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(fixture["grant"].clone()).unwrap();let authored=fixture["authoredSql"].as_str().unwrap();
 let script="import{Database}from'bun:sqlite';const f=JSON.parse(await Bun.stdin.text());const reference=new Database(':memory:');reference.run(f.authoredSql);const expected=reference.query(`SELECT name,sql FROM sqlite_master WHERE type='table'`).all();const results=f.cases.map(c=>{const db=new Database(':memory:');try{db.run(c.sql);const authored=new Database(':memory:');try{authored.run(c.authoredSql??f.authoredSql);const expected=authored.query(`SELECT name,sql FROM sqlite_master WHERE type='table'`).all();return JSON.stringify(db.query(`SELECT name,sql FROM sqlite_master WHERE type='table'`).all())===JSON.stringify(expected)}finally{authored.close()}}catch{return false}finally{db.close()}});reference.run('INSERT INTO retained_value VALUES(?,?)',f.extentRow);const extent=reference.query('SELECT count(*) AS rows,sum(8+length(CAST(value AS BLOB))) AS bytes FROM retained_value').get();const extents=f.extentCases.map(c=>extent.rows<=c.maximumRows&&2<=c.maximumColumns&&extent.bytes<=c.maximumValueBytes);reference.close();await Bun.write(Bun.stdout,JSON.stringify({schema:results,extents}));";
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(fixture.to_string().as_bytes()).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let expected:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();
 for(case,independent)in fixture["cases"].as_array().unwrap().iter().zip(expected["schema"].as_array().unwrap()){let sql=case["sql"].as_str().unwrap();let declaration=case["authoredSql"].as_str().unwrap_or(authored);let name=case["table"].as_str().unwrap_or(fixture["table"].as_str().unwrap());let database=SqliteDatabase{tables:vec![super::super::super::SqliteTable{name:name.into(),sql:sql.into(),rows:Vec::new()}]};let mut sql_observer=|_|true;let mut native_observer=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_observer,Default::default());let mut native=NativeDecodeControl::new(0,&mut native_observer);let mut body=OriginalSchemaWallet{grant,progress:Default::default()};let mut port=Port{control:&mut control,native:Direction::Decode(&mut native),body:&mut body};let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||validate_schema_sql(&database,declaration,&mut port));assert_eq!(result.is_ok(),case["accepted"].as_bool().unwrap(),"{}",case["id"]);assert_eq!(independent.as_bool().unwrap(),case["oracleAccepted"].as_bool().unwrap());assert_eq!((born,released),(0,0));assert!(body.progress.copied_items>0);assert!(control.performed_work()>0);assert_eq!(native.owned_bytes(),0);}
 for(case,independent)in fixture["extentCases"].as_array().unwrap().iter().zip(expected["extents"].as_array().unwrap()){
  let database=SqliteDatabase{tables:vec![super::super::super::SqliteTable{name:fixture["table"].as_str().unwrap().into(),sql:authored.into(),rows:vec![SqliteRow{rowid:1,values:vec![SqliteValue::Integer(fixture["extentRow"][0].as_i64().unwrap()),SqliteValue::Text(fixture["extentRow"][1].as_str().unwrap().into())]}]}]};let limits=super::super::super::SqliteDatabaseLimits{max_rows:case["maximumRows"].as_u64().unwrap()as usize,max_columns:case["maximumColumns"].as_u64().unwrap()as usize,max_value_bytes:case["maximumValueBytes"].as_u64().unwrap()as usize,..Default::default()};let mut sql_observer=|_|true;let mut native_observer=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_observer,limits);let mut native=NativeDecodeControl::new(0,&mut native_observer);let mut body=OriginalSchemaWallet{grant,progress:Default::default()};let mut port=Port{control:&mut control,native:Direction::Decode(&mut native),body:&mut body};let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||check_database(&database,&mut port));assert_eq!(result.is_ok(),case["accepted"].as_bool().unwrap(),"{}",case["id"]);assert_eq!(result.is_ok(),independent.as_bool().unwrap());assert_eq!((born,released),(0,0));assert!(body.progress.copied_items>0);assert!(control.performed_work()>0);assert_eq!(native.owned_bytes(),0);
 }
 let database=SqliteDatabase{tables:vec![super::super::super::SqliteTable{name:fixture["table"].as_str().unwrap().into(),sql:authored.into(),rows:Vec::new()}]};let mut sql_observer=|_|true;let mut native_observer=|_|true;let mut control=SqliteSnapshotControl::new(&mut sql_observer,Default::default());let mut native=NativeDecodeControl::new(0,&mut native_observer);let mut body=OriginalSchemaWallet{grant:RetainedCloneGrant{maximum_items:0,..grant},progress:Default::default()};let mut port=Port{control:&mut control,native:Direction::Decode(&mut native),body:&mut body};let(error,born,released)=semio_framework_trace_memory_testing::observe_backing(||validate_schema_sql(&database,authored,&mut port).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!((born,released),(0,0));assert_eq!(body.progress,Default::default());assert_eq!(control.performed_work(),0);
}
#[test]
fn sqlite_settlement_keeps_typed_primary_and_existing_native_context(){
 use semio_framework_io_control::NativeSnapshotFailure;
 use semio_framework_value_native_owned::OriginalReceivingPrimary;
 use semio_framework_value::retirement::controlled::ControlledRetirement;
 use semio_framework_value::ErasedSnapshotRetirement;
 let f:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🚪️io/⏱️control/🧾️failure/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let p:RetainedCloneProgress=serde_json::from_value(f["progress"].clone()).unwrap();let value=|index:usize|ValueError::new(ValueRefusalKind::InvalidValue,f["messages"][index].as_str().unwrap().to_owned());
 let original=NativeSnapshotFailure::from(OriginalReceivingPrimary{retirement_failure:None,work_refusal:None,primary:Some(value(0)),quote_refusal:Some(value(1)),allocation_refusal:Some(value(2)),allocation_failure:None,native_allocation:None,receipt_refusal:None,progress:p}).with_context_refusal(value(3));let primary=original.receiving_primary().unwrap().primary.as_ref().unwrap().message.as_ptr();let context=original.context_refusal().unwrap().message.as_ptr();
 let calls=std::cell::Cell::new(0u64);let mut callback=|_|{calls.set(calls.get()+1);false};let mut control=SqliteSnapshotControl::new(&mut callback,Default::default());let settlement=super::ReceivingSettlement::new(&mut control,0,semio_framework_io_sqlite_snapshot::SqliteSnapshotPhase::ProjectSnapshot);settlement.finish_body(0).unwrap();let completed=f["sqlite"]["completed"].as_u64().unwrap()as usize;let total=f["sqlite"]["total"].as_u64().unwrap()as usize;assert!(!settlement.observe(0,completed,total));assert!(!settlement.observe(0,completed,total));assert_eq!(calls.get(),f["sqlite"]["callbackCalls"].as_u64().unwrap());
 let(original,born,released)=semio_framework_trace_memory_testing::observe_backing(||settlement.refused_failure(0,original));assert_eq!((born,released),(0,0));assert_eq!(original.receiving_primary().unwrap().primary.as_ref().unwrap().message.as_ptr(),primary);assert_eq!(original.context_refusal().unwrap().message.as_ptr(),context);assert_eq!(original.settlement_refusal().unwrap().kind,ValueRefusalKind::Canceled);assert_eq!(original.settlement_refusal().unwrap().message.as_ref(),f["sqlite"]["settlementMessage"].as_str().unwrap());assert_eq!(original.receipt_refusal(),None);assert_eq!(original.retained_progress(),p);drop(settlement);
 let g=serde_json::from_value(f["closeGrant"].clone()).unwrap();let mut owner=ControlledRetirement::new(original).ok().unwrap();for _ in 0..f["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||owner.step(g));let p=result.unwrap().progress();assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));}assert!(owner.terminal_is_empty());
}

#[test]
fn effect_unwind_posts_actual_progress_into_the_caller_failure_slot(){
 use semio_framework_io_control::NativeSnapshotBodyWallet;
 use semio_framework_value::{RetirementDemand,ValueError};
 use semio_framework_value_native_owned::native_decoding::{NativeDecodeConstructionRecipient,NativeDecodeWorkRecipient};
 struct Work;
 impl NativeDecodeWorkRecipient for Work{fn admits(&mut self,_:u64,_:u64)->Result<bool>{Ok(true)}}
 struct Physical{grant:RetainedCloneGrant,submitted:RetainedCloneProgress}
 impl NativeDecodeConstructionRecipient for Physical{
  fn submitted(&self)->RetainedCloneProgress{self.submitted}
  fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant>{Ok(self.grant)}
  fn accept(&mut self,_:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<()>{self.submitted=self.submitted.checked_add(progress)?;Err(ValueError::literal(ValueRefusalKind::Canceled,"physical refusal"))}
 }
 let grant=RetainedCloneGrant{maximum_items:10,maximum_copy_bytes:10,maximum_capacity_bytes:10,maximum_release_bytes:10,maximum_depth:2};
 let mut native_observer=|_|true;let mut sql_observer=|_|true;let mut native=NativeDecodeControl::new(10,&mut native_observer);let mut control=SqliteSnapshotControl::new(&mut sql_observer,Default::default());let mut work=Work;let mut physical=Physical{grant,submitted:Default::default()};let mut body=NativeSnapshotBodyWallet::new(grant);let mut progress=semio_framework_io_control::NativeSnapshotEffectProgress::default();let mut failure=None;let mut slot=0u8;
 let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{
  let _:Result<()>=native.with_work_recipient(&mut work,|native|native.with_construction_recipient(&mut physical,|native|{
   let mut port=Port{control:&mut control,native:Direction::Decode(native),body:&mut body};
   let _=port.effect(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1,maximum_depth:1,..Default::default()},&mut progress,&mut failure,&mut |performed,physical|{slot=7;*performed=true;*physical=RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()};panic!("effect unwind")});Ok(())
  }));
 }));
 assert!(panic.is_err());assert_eq!(slot,7);assert_eq!(physical.submitted.copied_bytes,1);assert_eq!(body.progress().copied_bytes,1);assert_eq!(failure.unwrap().receipt_refusal().unwrap().message.as_ref(),"physical refusal");
}
